const String _styles = '''
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    font-family: Inter, "Segoe UI", system-ui, -apple-system, sans-serif;
    background: #181C27;
    color: #FFFFFF;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    padding: 24px;
    -webkit-font-smoothing: antialiased;
  }
  .card {
    background: #1E2633;
    border: 1px solid #2C3647;
    border-radius: 20px;
    padding: 40px 36px 32px;
    max-width: 400px;
    width: 100%;
    text-align: center;
    box-shadow: 0 24px 48px rgba(0, 0, 0, 0.35);
  }
  .logo { width: 64px; height: 64px; margin: 0 auto 28px; }
  .logo svg { width: 100%; height: 100%; display: block; }
  .status {
    width: 44px;
    height: 44px;
    margin: 0 auto 18px;
    border-radius: 50%;
    border: 1.5px solid #FFFFFF;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 0 20px rgba(255, 255, 255, 0.15);
  }
  .status svg { width: 22px; height: 22px; }
  .status.error { border-color: #A0ABBA; box-shadow: none; }
  h1 { font-size: 21px; font-weight: 700; letter-spacing: -0.02em; margin-bottom: 10px; }
  p { font-size: 15px; color: #A0ABBA; line-height: 1.55; }
  .hint { font-size: 13px; color: #7F8C9D; margin-top: 24px; }
  .code {
    font-family: Consolas, ui-monospace, monospace;
    font-size: 12px;
    color: #7F8C9D;
    margin-top: 16px;
    word-break: break-all;
  }
''';

const String _checkIcon =
    '<svg viewBox="0 0 24 24" fill="none" stroke="#FFFFFF" stroke-width="2" stroke-linecap="round" '
    'stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>';

const String _crossIcon =
    '<svg viewBox="0 0 24 24" fill="none" stroke="#A0ABBA" stroke-width="2" stroke-linecap="round">'
    '<path d="M7 7l10 10M17 7L7 17"/></svg>';

String _page({required String title, required String body}) => '<!DOCTYPE html>\n'
    '<html lang="es">\n<head>\n'
    '<meta charset="UTF-8">\n'
    '<meta name="viewport" content="width=device-width, initial-scale=1.0">\n'
    '<title>$title</title>\n'
    '<link rel="preconnect" href="https://fonts.googleapis.com">\n'
    '<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;700&display=swap" rel="stylesheet">\n'
    '<style>$_styles</style>\n'
    '</head>\n<body>\n<main class="card">\n'
    '<div class="logo">$_logoSvg</div>\n'
    '$body\n'
    '</main>\n</body>\n</html>';

/// Escapa texto que viene de la URL del callback antes de meterlo en la página.
String _escape(String s) => s
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');

String desktopAuthSuccessPage() => _page(
      title: 'Sesión iniciada · Syncora Player',
      body: '<div class="status">$_checkIcon</div>\n'
          '<h1>Sesión iniciada</h1>\n'
          '<p>Ya puedes volver a Syncora Player.</p>\n'
          '<p class="hint">Puedes cerrar esta pestaña.</p>\n'
          '<script>\n'
          '  try { window.close(); } catch (e) {}\n'
          '  setTimeout(function () { try { window.close(); } catch (e) {} }, 500);\n'
          '</script>',
    );

String desktopAuthErrorPage(String error, String? description) => _page(
      title: 'No se pudo iniciar sesión · Syncora Player',
      body: '<div class="status error">$_crossIcon</div>\n'
          '<h1>No se pudo iniciar sesión</h1>\n'
          '<p>${_escape(description ?? 'Ocurrió un error durante el inicio de sesión.')}</p>\n'
          '<p class="hint">Vuelve a Syncora Player e inténtalo de nuevo.</p>\n'
          '<p class="code">${_escape(error)}</p>',
    );
